// Copies the brand palette (`--brand-*`) of the Design System into src/styles/tokens.css (ADR-014 2.5).
// Source of truth: design/wireframes/assets/tokens.css, GENERATED by UXD (design/tools/gen_tokens.py, DS v0.4.1 –
// Brand Guidelines v1.0). The landing takes only the brand group: the app tokens (surface, side, status colours,
// dark mode) drift slightly from the palette and must not reach the public site.
// Run `pnpm --filter @ottimo/landing-web sync:tokens` after UXD regenerates the tokens;
// src/styles/brand.test.ts fails CI when the copy is stale.
import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import prettier from 'prettier';

export const SRC_URL = new URL('../../../design/wireframes/assets/tokens.css', import.meta.url);
export const OUT_URL = new URL('../src/styles/tokens.css', import.meta.url);

/**
 * Brand declarations of the first `:root` block (the palette is constant in both colour modes).
 * @param {string} css
 * @returns {[string, string][]}
 */
export function extractBrand(css) {
  const root = css.match(/:root\s*\{([^}]*)\}/);
  if (!root) throw new Error('tokens.css: no :root block');
  const decls = [...root[1].matchAll(/(--brand-[a-z]+)\s*:\s*([^;]+);/g)].map(
    /** @returns {[string, string]} */ (m) => [m[1], m[2].trim()],
  );
  if (decls.length === 0) throw new Error('tokens.css: no --brand-* token');
  return decls;
}

export async function render() {
  const decls = extractBrand(await readFile(SRC_URL, 'utf8'));
  const body = decls.map(([k, v]) => `  ${k}: ${v};`).join('\n');
  const source =
    '/* GENERATED by apps/landing-web/scripts/sync-tokens.mjs from design/wireframes/assets/tokens.css\n' +
    '   (DS brand group, OTTIMO Brand Guidelines v1.0) – do not edit. Landing CSS uses only these colours. */\n' +
    `:root {\n${body}\n}\n`;
  const options = (await prettier.resolveConfig(fileURLToPath(OUT_URL))) ?? {};
  return prettier.format(source, { ...options, parser: 'css' });
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  await writeFile(OUT_URL, await render());
  console.log('src/styles/tokens.css written');
}
